const input = $input.first().json;
const body = input.body || input;
const question = body.question || body.q || '';

if (!question) return [{ json: { error: true, message: 'Question required' } }];

const prompt = `You are a data analyst for a CRM/Marketing platform. Convert this natural language question into a PostgreSQL query.

Available tables:
- contacts (id, email, first_name, last_name, company, lead_score, lead_status, source, created_at)
- deals (id, contact_id, deal_name, deal_value, stage, probability, assigned_to, created_at)
- lead_activities (id, contact_id, activity_type, activity_data, score_impact, created_at)
- tracked_keywords (id, keyword, target_url, is_active)
- keyword_rankings (id, keyword_id, position, previous_position, search_volume, checked_at)
- backlinks (id, source_url, target_url, domain_rating, is_active, first_seen)

Question: "${question}"

Respond with ONLY a JSON object: {"sql": "YOUR_SELECT_QUERY", "explanation": "brief explanation"}
Rules: Only SELECT queries. No INSERT/UPDATE/DELETE. Limit results to 20.`;

return [{ json: { question, prompt, client_id: body.client_id } }];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '';

let parsed = {};
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : '{}');
} catch(e) {
  return [{ json: { error: true, message: 'Could not parse AI response' } }];
}

const sql = parsed.sql || '';

// Safety check: only allow SELECT
if (!sql.trim().toUpperCase().startsWith('SELECT') || sql.includes('DROP') || sql.includes('DELETE') || sql.includes('INSERT') || sql.includes('UPDATE') || sql.includes('ALTER')) {
  return [{ json: { error: true, message: 'Unsafe query detected' } }];
}

return [{ json: { sql, explanation: parsed.explanation || '', question: $node['Build Query Prompt'].json.question } }];

const results = $input.all().map(i => i.json);
const queryInfo = $node['Validate SQL'].json;

return [{ json: {
  success: true,
  question: queryInfo.question,
  explanation: queryInfo.explanation,
  sql: queryInfo.sql,
  results: results,
  result_count: results.length
}}];
